//! Triton-compiled Metal kernel dispatch for Moonshine encoder.
//!
//! Loads pre-compiled .metal source files (generated by Triton AOT compiler),
//! compiles them into Metal compute pipelines, and provides dispatch functions
//! for each kernel type.

use anyhow::Result;
use candle_core::{DType, MetalDevice, MetalStorage, Shape, Storage, Tensor};
use candle_metal_kernels::metal::ComputePipeline;
use objc2_metal::MTLSize;
use std::path::{Path, PathBuf};

// Embed all .metal kernel sources at compile time so the binary is self-contained.
// Uses cfg(target_arch) to select Apple Silicon vs Intel shader variants.
macro_rules! embed_kernels {
    ($dir:literal; $($name:literal),* $(,)?) => {
        fn embedded_metal_source(name: &str) -> Option<&'static str> {
            match name {
                $($name => Some(include_str!(concat!(
                    "../../triton/third_party/metal/", $dir, "/", $name, ".metal"
                ))),)*
                _ => None,
            }
        }
    }
}

// Shared kernel list — only the directory and arch-specific extras differ.
macro_rules! metal_kernels {
    ($dir:literal $(, $extra:literal)*) => {
        embed_kernels!($dir;
            // Encoder
            "matmul_fp16_64x64x32",
            "matmul_fp16_128x128x32",
            "matmul_bias_fp16_32x32x32",
            "matmul_bias_fp16_64x64x32",
            "matmul_bias_fp16_128x128x32",
            "matmul_bias_gelu_fp16_32x32x32",
            "matmul_bias_gelu_fp16_64x64x32",
            "matmul_bias_gelu_fp16_128x128x32",
            "layernorm_unit_offset_768",
            "layernorm_bare_768",
            "residual_add_fp16",
            "flash_attention_fwd_32x32x64",
            "gelu_fp16",
            "bias_add_fp16",
            // Decoder
            "gemv_f16w",
            "gemv_bias_f16w",
            "layernorm_standard_f32in_640",
            "residual_add_f32",
            "convert_f32_to_f16",
            "attention_decode_1d_d80",
            "attention_decode_splitkv_partial",
            "attention_decode_splitkv_reduce",
            "rope_qk_cache_fused",
            "kv_cache_append",
            "glu_silu_fused",
            "residual_add_layernorm_fused",
            "gemv_bias_glu_fused",
            "gemv_resadd_ln_fused",
            "gemv_splitk_partial",
            "gemv_splitk_bias_reduce",
            "gemv_splitk_reduce",
            "gemv_splitk_reduce_resadd_ln",
            "gemv_qkv_splitk_partial",
            "gemv_qkv_splitk_reduce",
            "gemv_glu_splitk_partial",
            "gemv_glu_splitk_reduce",
            $($extra,)*
        );
    }
}

#[cfg(target_arch = "aarch64")]
metal_kernels!("moonshine_metal");

#[cfg(target_arch = "x86_64")]
metal_kernels!("moonshine_metal_intel", "rel_pos_fa2_fwd_16x32x128");

fn cdiv(a: usize, b: usize) -> usize {
    (a + b - 1) / b
}

/// Clamp threadgroup size to pipeline's maximum (critical for Intel GPUs with < 1024 limit).
fn tg_size(pipeline: &ComputePipeline, requested: usize) -> MTLSize {
    let max = pipeline.max_total_threads_per_threadgroup();
    MTLSize { width: requested.min(max), height: 1, depth: 1 }
}

/// All compiled Triton kernel pipelines for the Moonshine encoder.
pub struct TritonKernels {
    pub matmul_64x64: ComputePipeline,
    pub matmul_128x128: Option<ComputePipeline>,
    pub matmul_bias_32x32: ComputePipeline,
    pub matmul_bias_64x64: Option<ComputePipeline>,
    pub matmul_bias_128x128: Option<ComputePipeline>,
    pub matmul_bias_gelu_32x32: ComputePipeline,
    pub matmul_bias_gelu_64x64: Option<ComputePipeline>,
    pub matmul_bias_gelu_128x128: Option<ComputePipeline>,
    pub layernorm_unit_offset: ComputePipeline,
    pub layernorm_bare: Option<ComputePipeline>,
    pub residual_add: ComputePipeline,
    pub flash_attention: ComputePipeline,
    pub rel_pos_fa2: Option<ComputePipeline>,
    pub gelu: ComputePipeline,
    pub bias_add: ComputePipeline,
}

impl TritonKernels {
    /// Load kernels from embedded .metal sources (or fall back to disk).
    pub fn load(metal_device: &MetalDevice, kernel_dir: &Path) -> Result<Self> {
        let device = metal_device.device();

        let load = |name: &str, func_name: &str| -> Result<ComputePipeline> {
            eprint!("    {name}...");
            let owned;
            let source = match embedded_metal_source(name) {
                Some(s) => s,
                None => {
                    let path = kernel_dir.join(format!("{name}.metal"));
                    owned = std::fs::read_to_string(&path)
                        .map_err(|e| anyhow::anyhow!("Failed to read {}: {e}", path.display()))?;
                    &owned
                }
            };
            let lib = device
                .new_library_with_source(source, None)
                .map_err(|e| anyhow::anyhow!("Failed to compile {name}: {e}"))?;
            let func = lib
                .get_function(func_name, None)
                .map_err(|e| anyhow::anyhow!("Function {func_name} not found in {name}: {e}"))?;
            let pipeline = device
                .new_compute_pipeline_state_with_function(&func)
                .map_err(|e| anyhow::anyhow!("Pipeline failed for {name}: {e}"))?;
            eprintln!(" ok (max_threads={})", pipeline.max_total_threads_per_threadgroup());
            Ok(pipeline)
        };

        Ok(Self {
            matmul_64x64: load("matmul_fp16_64x64x32", "matmul_fp16")?,
            matmul_128x128: load("matmul_fp16_128x128x32", "matmul_fp16").ok(),
            matmul_bias_32x32: load("matmul_bias_fp16_32x32x32", "matmul_bias_fp16")?,
            matmul_bias_64x64: {
                match load("matmul_bias_fp16_64x64x32", "matmul_bias_fp16") {
                    Ok(p) => Some(p),
                    Err(e) => { eprintln!(" SKIP ({e})"); None }
                }
            },
            matmul_bias_128x128: {
                match load("matmul_bias_fp16_128x128x32", "matmul_bias_fp16") {
                    Ok(p) => Some(p),
                    Err(e) => { eprintln!(" SKIP ({e})"); None }
                }
            },
            matmul_bias_gelu_32x32: load("matmul_bias_gelu_fp16_32x32x32", "matmul_bias_gelu_fp16")?,
            matmul_bias_gelu_64x64: {
                match load("matmul_bias_gelu_fp16_64x64x32", "matmul_bias_gelu_fp16") {
                    Ok(p) => Some(p),
                    Err(e) => { eprintln!(" SKIP ({e})"); None }
                }
            },
            matmul_bias_gelu_128x128: {
                match load("matmul_bias_gelu_fp16_128x128x32", "matmul_bias_gelu_fp16") {
                    Ok(p) => Some(p),
                    Err(e) => { eprintln!(" SKIP ({e})"); None }
                }
            },
            layernorm_unit_offset: load("layernorm_unit_offset_768", "layernorm_unit_offset")?,
            layernorm_bare: load("layernorm_bare_768", "layernorm_bare").ok(),
            residual_add: load("residual_add_fp16", "residual_add")?,
            flash_attention: load("flash_attention_fwd_32x32x64", "flash_attention_fwd")?,
            rel_pos_fa2: load("rel_pos_fa2_fwd_16x32x128", "rel_pos_fa2_fwd").ok(),
            gelu: load("gelu_fp16", "gelu_forward")?,
            bias_add: load("bias_add_fp16", "bias_add")?,
        })
    }
}

/// Create an empty F16 output tensor on the Metal device.
pub fn empty_f16(device: &MetalDevice, shape: impl Into<Shape>) -> Result<Tensor> {
    let shape: Shape = shape.into();
    let n = shape.elem_count();
    let buffer = device.new_buffer(n, DType::F16, "triton_out")?;
    let storage = MetalStorage::new(buffer, device.clone(), n, DType::F16);
    Ok(Tensor::from_storage(
        Storage::Metal(storage),
        shape,
        candle_core::op::BackpropOp::none(),
        false,
    ))
}

/// Helper: extract MetalStorage from a tensor. Panics on non-Metal tensor.
macro_rules! with_metal_buffers {
    // 3 tensors + output
    ($a:expr, $b:expr, $c:expr, $out:expr, |$a_buf:ident, $a_off:ident, $b_buf:ident, $b_off:ident, $c_buf:ident, $c_off:ident, $o_buf:ident, $o_off:ident| $body:block) => {{
        let (sa, la) = $a.storage_and_layout();
        let (sb, lb) = $b.storage_and_layout();
        let (sc, lc) = $c.storage_and_layout();
        let (so, lo) = $out.storage_and_layout();
        let $a_off = la.start_offset() * $a.dtype().size_in_bytes();
        let $b_off = lb.start_offset() * $b.dtype().size_in_bytes();
        let $c_off = lc.start_offset() * $c.dtype().size_in_bytes();
        let $o_off = lo.start_offset() * $out.dtype().size_in_bytes();
        match (&*sa, &*sb, &*sc, &*so) {
            (Storage::Metal(ma), Storage::Metal(mb), Storage::Metal(mc), Storage::Metal(mo)) => {
                let $a_buf = ma.buffer();
                let $b_buf = mb.buffer();
                let $c_buf = mc.buffer();
                let $o_buf = mo.buffer();
                $body
            }
            _ => anyhow::bail!("All tensors must be on Metal device"),
        }
    }};
    // 2 tensors + output
    ($a:expr, $b:expr, $out:expr, |$a_buf:ident, $a_off:ident, $b_buf:ident, $b_off:ident, $o_buf:ident, $o_off:ident| $body:block) => {{
        let (sa, la) = $a.storage_and_layout();
        let (sb, lb) = $b.storage_and_layout();
        let (so, lo) = $out.storage_and_layout();
        let $a_off = la.start_offset() * $a.dtype().size_in_bytes();
        let $b_off = lb.start_offset() * $b.dtype().size_in_bytes();
        let $o_off = lo.start_offset() * $out.dtype().size_in_bytes();
        match (&*sa, &*sb, &*so) {
            (Storage::Metal(ma), Storage::Metal(mb), Storage::Metal(mo)) => {
                let $a_buf = ma.buffer();
                let $b_buf = mb.buffer();
                let $o_buf = mo.buffer();
                $body
            }
            _ => anyhow::bail!("All tensors must be on Metal device"),
        }
    }};
}

// ── Dispatch functions ──────────────────────────────────────────────────────

/// Dispatch matmul: C[M,N] = A[M,K] @ B[K,N]
///
/// B must be stored as [K, N] row-major (stride_bk=N, stride_bn=1).
/// The kernel's vec4 cooperative load requires the N dimension to be contiguous.
///
/// For weight matrices stored as [N, K] (e.g., from GGUF), transpose before calling:
///   `weight.t()?.contiguous()?`
pub fn triton_matmul(
    device: &MetalDevice,
    pipeline: &ComputePipeline,
    a: &Tensor,
    b: &Tensor,
    m: usize,
    n: usize,
    k: usize,
    block_m: usize,
    block_n: usize,
) -> Result<Tensor> {
    let out = empty_f16(device, (m, n))?;

    with_metal_buffers!(a, b, &out, |a_buf, a_off, b_buf, b_off, o_buf, o_off| {
        let encoder = device.command_encoder()?;
        encoder.set_compute_pipeline_state(pipeline);
        encoder.set_buffer(0, Some(a_buf), a_off);
        encoder.set_buffer(1, Some(b_buf), b_off);
        encoder.set_buffer(2, Some(o_buf), o_off);
        encoder.set_bytes(3, &(m as i32));
        encoder.set_bytes(4, &(n as i32));
        encoder.set_bytes(5, &(k as i32));
        encoder.set_bytes(6, &(k as i32));      // stride_am = K
        encoder.set_bytes(7, &1i32);            // stride_ak = 1
        encoder.set_bytes(8, &(n as i32));      // stride_bk = N (B=[K,N], row-major)
        encoder.set_bytes(9, &1i32);            // stride_bn = 1
        encoder.set_bytes(10, &(n as i32));     // stride_cm = N
        encoder.set_bytes(11, &1i32);           // stride_cn = 1

        let grid = MTLSize {
            width: cdiv(m, block_m),
            height: cdiv(n, block_n),
            depth: 1,
        };
        encoder.dispatch_thread_groups(grid, tg_size(pipeline, 1024));
        Ok::<(), anyhow::Error>(())
    })?;

    Ok(out)
}

/// Dispatch matmul + bias: C[M,N] = A[M,K] @ B[K,N] + bias[N]
///
/// B must be [K, N] row-major. Transpose weights before calling.
/// `block_m`/`block_n` must match the compiled kernel tile size.
pub fn triton_matmul_bias(
    device: &MetalDevice,
    pipeline: &ComputePipeline,
    a: &Tensor,
    b: &Tensor,
    bias: &Tensor,
    m: usize,
    n: usize,
    k: usize,
    block_m: usize,
    block_n: usize,
) -> Result<Tensor> {
    let out = empty_f16(device, (m, n))?;

    with_metal_buffers!(a, b, bias, &out, |a_buf, a_off, b_buf, b_off, bias_buf, bias_off, o_buf, o_off| {
        let encoder = device.command_encoder()?;
        encoder.set_compute_pipeline_state(pipeline);
        encoder.set_buffer(0, Some(a_buf), a_off);
        encoder.set_buffer(1, Some(b_buf), b_off);
        encoder.set_buffer(2, Some(bias_buf), bias_off);
        encoder.set_buffer(3, Some(o_buf), o_off);
        encoder.set_bytes(4, &(m as i32));
        encoder.set_bytes(5, &(n as i32));
        encoder.set_bytes(6, &(k as i32));
        encoder.set_bytes(7, &(k as i32));      // stride_am = K
        encoder.set_bytes(8, &1i32);            // stride_ak = 1
        encoder.set_bytes(9, &(n as i32));      // stride_bk = N (B=[K,N])
        encoder.set_bytes(10, &1i32);           // stride_bn = 1
        encoder.set_bytes(11, &(n as i32));     // stride_cm = N
        encoder.set_bytes(12, &1i32);           // stride_cn = 1

        let grid = MTLSize {
            width: cdiv(m, block_m),
            height: cdiv(n, block_n),
            depth: 1,
        };
        encoder.dispatch_thread_groups(grid, tg_size(pipeline, 1024));
        Ok::<(), anyhow::Error>(())
    })?;

    Ok(out)
}

