        encoder.set_bytes(5, &(n as i32));
        encoder.set_bytes(6, &(k as i32));
        encoder.set_bytes(7, &(k as i32));      // stride_am = K
        encoder.set_bytes(8, &1i32);            // stride_ak = 1
        encoder.set_bytes(9, &(n as i32));      // stride_bk = N (B=[K,N])
