/// Dispatch unit-offset layernorm: out = LN(x) * (gamma + 1.0)
pub fn triton_layernorm_unit_offset(
    device: &MetalDevice,
    pipeline: &ComputePipeline,
    x: &Tensor,
    gamma: &Tensor,
    n_rows: usize,
    n_cols: usize,
) -> Result<Tensor> {
    let out = empty_f16(device, (n_rows, n_cols))?;

    with_metal_buffers!(x, gamma, &out, |x_buf, x_off, g_buf, g_off, o_buf, o_off| {
        let encoder = device.command_encoder()?;
        encoder.set_compute_pipeline_state(pipeline);
        encoder.set_buffer(0, Some(x_buf), x_off);
        encoder.set_buffer(1, Some(g_buf), g_off);
        encoder.set_buffer(2, Some(o_buf), o_off);
        encoder.set_bytes(3, &(n_rows as i32));
        encoder.set_bytes(4, &(n_cols as i32));
        encoder.set_bytes(5, &(n_cols as i32));
        encoder.set_bytes(6, &(n_cols as i32));

        let grid = MTLSize { width: n_rows as usize, height: 1, depth: 1 };
        encoder.dispatch_thread_groups(grid, tg_size(pipeline, n_cols));
        Ok::<(), anyhow::Error>(())
    })?;

    Ok(out)
}

/// Dispatch bare layernorm: out = (x - mean) / sqrt(var + eps)
/// No gamma scaling — gamma is baked into downstream weights.
pub fn triton_layernorm_bare(
    device: &MetalDevice,
    pipeline: &ComputePipeline,
    x: &Tensor,
    n_rows: usize,
    n_cols: usize,
) -> Result<Tensor> {
    let out = empty_f16(device, (n_rows, n_cols))?;

    {
        let (sx, lx) = x.storage_and_layout();
        let (so, lo) = out.storage_and_layout();
        let x_off = lx.start_offset() * x.dtype().size_in_bytes();
        let o_off = lo.start_offset() * out.dtype().size_in_bytes();
        match (&*sx, &*so) {
            (Storage::Metal(mx), Storage::Metal(mo)) => {
                let encoder = device.command_encoder()?;
                encoder.set_compute_pipeline_state(pipeline);
                encoder.set_buffer(0, Some(mx.buffer()), x_off);
                encoder.set_buffer(1, Some(mo.buffer()), o_off);
                encoder.set_bytes(2, &(n_rows as i32));
                encoder.set_bytes(3, &(n_cols as i32));
                encoder.set_bytes(4, &(n_cols as i32));
                encoder.set_bytes(5, &(n_cols as i32));

                let grid = MTLSize { width: n_rows, height: 1, depth: 1 };
                encoder.dispatch_thread_groups(grid, tg_size(pipeline, n_cols));
            }
            _ => anyhow::bail!("Tensors must be on Metal device"),
        }
    }

    Ok(out)
}

/// Dispatch residual add: out = x + residual (element-wise F16)
pub fn triton_residual_add(
    device: &MetalDevice,
    pipeline: &ComputePipeline,
    x: &Tensor,
    residual: &Tensor,
    n_elements: usize,
) -> Result<Tensor> {
    let out = empty_f16(device, x.shape())?;

    with_metal_buffers!(x, residual, &out, |x_buf, x_off, r_buf, r_off, o_buf, o_off| {
        let encoder = device.command_encoder()?;
        encoder.set_compute_pipeline_state(pipeline);
        encoder.set_buffer(0, Some(x_buf), x_off);
        encoder.set_buffer(1, Some(r_buf), r_off);
        encoder.set_buffer(2, Some(o_buf), o_off);
        encoder.set_bytes(3, &(n_elements as i32));

        let tg_w = tg_size(pipeline, 1024).width;
        let grid = MTLSize { width: cdiv(n_elements, tg_w) as usize, height: 1, depth: 1 };
        encoder.dispatch_thread_groups(grid, MTLSize { width: tg_w, height: 1, depth: 1 });
        Ok::<(), anyhow::Error>(())
    })?;

    Ok(out)
}

/// Dispatch GELU activation: out[i] = gelu(x[i]) (element-wise F16)
///
/// The kernel processes 1024 elements per threadgroup.
pub fn triton_gelu(
    device: &MetalDevice,
    pipeline: &ComputePipeline,
    x: &Tensor,
    n_elements: usize,
) -> Result<Tensor> {
    let out = empty_f16(device, x.shape())?;

    {
        let (sx, lx) = x.storage_and_layout();
        let (so, lo) = out.storage_and_layout();
        let x_off = lx.start_offset() * x.dtype().size_in_bytes();
        let o_off = lo.start_offset() * out.dtype().size_in_bytes();
        match (&*sx, &*so) {
            (Storage::Metal(mx), Storage::Metal(mo)) => {
                let encoder = device.command_encoder()?;
                encoder.set_compute_pipeline_state(pipeline);
                encoder.set_buffer(0, Some(mx.buffer()), x_off);
                encoder.set_buffer(1, Some(mo.buffer()), o_off);
                encoder.set_bytes(2, &(n_elements as i32));

                // Kernel hardcodes BLOCK_SIZE=1024
                let grid = MTLSize { width: cdiv(n_elements, 1024), height: 1, depth: 1 };
                encoder.dispatch_thread_groups(grid, tg_size(pipeline, 1024));
            }
            _ => anyhow::bail!("Tensors must be on Metal device"),
        }
    }

    Ok(out)
}

/// Dispatch bias add: out[i] = x[i] + bias[i % n_cols] (element-wise F16)
pub fn triton_bias_add(
    device: &MetalDevice,
    pipeline: &ComputePipeline,
    x: &Tensor,
    bias: &Tensor,
    n_elements: usize,
    n_cols: usize,
) -> Result<Tensor> {
    let out = empty_f16(device, x.shape())?;

    with_metal_buffers!(x, bias, &out, |x_buf, x_off, b_buf, b_off, o_buf, o_off| {
        let encoder = device.command_encoder()?;
        encoder.set_compute_pipeline_state(pipeline);
        encoder.set_buffer(0, Some(x_buf), x_off);
        encoder.set_buffer(1, Some(b_buf), b_off);
        encoder.set_buffer(2, Some(o_buf), o_off);
        encoder.set_bytes(3, &(n_elements as i32));
        encoder.set_bytes(4, &(n_cols as i32));

        let tg_w = tg_size(pipeline, 1024).width;
        let grid = MTLSize { width: cdiv(n_elements, tg_w), height: 1, depth: 1 };
        encoder.dispatch_thread_groups(grid, MTLSize { width: tg_w, height: 1, depth: 1 });
        Ok::<(), anyhow::Error>(())
    })?;

    Ok(out)
}

/// Dispatch Flash Attention 2 with sliding window.
///
/// Q, K, V, O: contiguous buffers with same strides.
/// stride_h: offset (in elements) between consecutive heads.
/// stride_m: offset (in elements) between consecutive rows within a head.
/// head_dim must be contiguous (stride 1).
///
/// Common layouts:
///   [n_heads, seq_len, D]: stride_h = seq_len * D, stride_m = D
///   [seq_len, n_heads, D]: stride_h = D, stride_m = n_heads * D
///
/// The kernel fuses QK^T, softmax with sliding window masking, and attn*V
/// in a single pass using online softmax (no materialised seq×seq matrix).
pub fn triton_flash_attention(
    device: &MetalDevice,
    pipeline: &ComputePipeline,
    q: &Tensor,
    k: &Tensor,
    v: &Tensor,
    out: &Tensor,
    n_heads: usize,
    seq_len: usize,
    _head_dim: usize,
    stride_h: i32,
    stride_qkv: i32,
    stride_o: i32,
    sm_scale: f32,
    window_left: i32,
    window_right: i32,
) -> Result<()> {
    with_metal_buffers!(q, k, v, out, |q_buf, q_off, k_buf, k_off, v_buf, v_off, o_buf, o_off| {
        let encoder = device.command_encoder()?;
        encoder.set_compute_pipeline_state(pipeline);
        encoder.set_buffer(0, Some(q_buf), q_off);
        encoder.set_buffer(1, Some(k_buf), k_off);
        encoder.set_buffer(2, Some(v_buf), v_off);
        encoder.set_buffer(3, Some(o_buf), o_off);
        encoder.set_bytes(4, &(seq_len as i32));
        encoder.set_bytes(5, &stride_h);
        encoder.set_bytes(6, &stride_qkv);
        encoder.set_bytes(7, &stride_o);
        encoder.set_bytes(8, &sm_scale);
        encoder.set_bytes(9, &window_left);
        encoder.set_bytes(10, &window_right);

        let grid = MTLSize {
            width: cdiv(seq_len, 32),
            height: n_heads,
            depth: 1,
        };
        encoder.dispatch_thread_groups(grid, tg_size(pipeline, 832));
        Ok::<(), anyhow::Error>(())
    })?;

    Ok(())
}

/// Create an empty F32 output tensor on the Metal device.
pub fn empty_f32(device: &MetalDevice, shape: impl Into<Shape>) -> Result<Tensor> {
    let shape: Shape = shape.into();
    let n = shape.elem_count();
    let buffer = device.new_buffer(n, DType::F32, "triton_f32_out")?;
    let storage = MetalStorage::new(buffer, device.clone(), n, DType::F32);
    Ok(Tensor::from_storage(
        Storage::Metal(storage),
        shape,
        candle_core::op::BackpropOp::none(),
        false,
    ))
}

/// Dispatch multi-head Flash Attention 2 with precomputed relative position bias.
///
/// Q: [nh, seq_len, d] F16 (Q + bias_u already added)
/// K, V: [nh, seq_len, d] F16
/// bias: [nh, seq_len, seq_len] F16 (unscaled relative position bias)
/// O: [nh, seq_len, d] F16 output
///
/// Kernel computes (QK^T + bias) * scale, then online softmax and attn·V.
/// Multi-head via program_id.y.
pub fn triton_rel_pos_fa2(
    device: &MetalDevice,
    pipeline: &ComputePipeline,
    q: &Tensor,
    k: &Tensor,
    v: &Tensor,
    bias: &Tensor,
    out: &Tensor,
    n_heads: usize,
    seq_len: usize,
    head_dim: usize,
    sm_scale: f32,
) -> Result<()> {
    let (sq, lq) = q.storage_and_layout();
    let (sk, lk) = k.storage_and_layout();
    let (sv, lv) = v.storage_and_layout();
    let (sb, lb) = bias.storage_and_layout();
    let (so, lo) = out.storage_and_layout();
    let q_off = lq.start_offset() * q.dtype().size_in_bytes();
    let k_off = lk.start_offset() * k.dtype().size_in_bytes();
    let v_off = lv.start_offset() * v.dtype().size_in_bytes();
    let b_off = lb.start_offset() * bias.dtype().size_in_bytes();
    let o_off = lo.start_offset() * out.dtype().size_in_bytes();

    let stride_h = (seq_len * head_dim) as i32;
    let bias_stride_h = (seq_len * seq_len) as i32;

    match (&*sq, &*sk, &*sv, &*sb, &*so) {
        (Storage::Metal(mq), Storage::Metal(mk), Storage::Metal(mv), Storage::Metal(mb), Storage::Metal(mo)) => {
            let encoder = device.command_encoder()?;
            encoder.set_compute_pipeline_state(pipeline);
            encoder.set_buffer(0, Some(mq.buffer()), q_off);
            encoder.set_buffer(1, Some(mk.buffer()), k_off);
            encoder.set_buffer(2, Some(mv.buffer()), v_off);
            encoder.set_buffer(3, Some(mb.buffer()), b_off);
            encoder.set_buffer(4, Some(mo.buffer()), o_off);
            encoder.set_bytes(5, &(seq_len as i32));
            encoder.set_bytes(6, &(head_dim as i32));
            encoder.set_bytes(7, &sm_scale);
            encoder.set_bytes(8, &stride_h);
            encoder.set_bytes(9, &bias_stride_h);

            let grid = MTLSize {
                width: cdiv(seq_len, 16),  // BM=16
                height: n_heads,
                depth: 1,
            };
            encoder.dispatch_thread_groups(grid, tg_size(pipeline, 512));
        }
        _ => anyhow::bail!("All tensors must be on Metal device"),
    }

    Ok(())
}

